// ---------------------------------------------------------------
// CLASSIFY ENQUIRY SOURCE
// Identifies which channel the enquiry arrived from, so downstream
// nodes can extract the right fields and pick the right reply tone.
// Non-enquiry email is dropped here (returns nothing).
// ---------------------------------------------------------------

// Portal/admin emails that come FROM a portal but are NOT prospect enquiries
// (e.g. Rightmove "your property has been made invisible", performance reports,
// invoices). These must never be treated as an enquiry.
const NOT_AN_ENQUIRY = /made (in)?visible|has been made (in)?visible|no longer (visible|listed)|performance (report|update|summary)|weekly (summary|report)|listing (report|performance|removed|expired)|your (invoice|receipt|statement|account)|payment (received|due|failed|reminder)|(price|listing) (recommendation|suggestion)|newsletter|webinar/i;

const out = [];

for (const item of $input.all()) {
  const d = item.json;

  // Input is the native Gmail Trigger (simple mode off) or the test node —
  // shapes vary slightly by version, so normalise defensively.
  const headers = d.headers || {};
  const from = String(
    d.from?.value?.[0]?.address || d.from || headers.from || ''
  ).toLowerCase();
  const subject = String(d.subject || headers.subject || '');
  const bodyHtml = String(d.html || d.textAsHtml || '');
  const bodyText = String(d.text || d.snippet || '');
  const body = bodyText || bodyHtml.replace(/<[^>]+>/g, ' ');

  // Drop portal notifications / admin mail before anything else.
  if (NOT_AN_ENQUIRY.test(subject)) continue;

  let source = null;

  if (from.includes('zoopla') || /tenant enquiry/i.test(subject)) {
    source = 'zoopla';
  } else if (from.includes('spareroom') || /response to your listing/i.test(subject)) {
    source = 'spareroom';
  } else if (
    from.includes('onthemarket') || /onthemarket\.com|your onthemarket team/i.test(body)
  ) {
    // OnTheMarket arrives forwarded (real sender user@example.com,
    // shown in the body) and its subject "Lettings enquiry from ..." would otherwise
    // match Rightmove below — so detect it by the OnTheMarket body marker first.
    source = 'onthemarket';
  } else if (
    from.includes('rightmove') ||
    // Real Rightmove enquiry subject is "Lettings enquiry: <prop> - Tenant from <area>";
    // tenant replies come back as "Re: Lettings enquiry: ...". Catch both.
    /lettings enquiry|has enquired about this property/i.test(subject)
  ) {
    source = 'rightmove';
  } else if (
    /viewing request from the website|property enquiry/i.test(subject)
  ) {
    source = 'website';
  }

  // Not an enquiry → skip (nothing pushed to output).
  if (!source) continue;

  out.push({
    json: {
      source,
      message_id: d.id || d.messageId || null,
      thread_id: d.threadId || null,
      rfc_message_id: d.rfc_message_id || d.messageId || (d.headers && d.headers['message-id']) || null,
      received_at: d.date || new Date().toISOString(),
      from_address: from,
      subject,
      body_text: body.slice(0, 12000),
      body_html: bodyHtml.slice(0, 20000)
    }
  });
}

return out;

// ---------------------------------------------------------------
// MERGE + NORMALISE
// Combine the classifier output with the extracted fields into one
// clean record, and work out which qualification data is MISSING.
//
// KEY LOGIC: Rightmove already supplies most qualification data.
// Zoopla / OnTheMarket / website enquiries do not. The reply must differ accordingly.
// ---------------------------------------------------------------

const results = [];

for (let i = 0; i < $input.all().length; i++) {
  const extracted = $input.all()[i].json.output || $input.all()[i].json;
  const meta = $('Classify Enquiry Source').all()[i].json;

  const rec = {
    source: meta.source,
    message_id: meta.message_id,
    thread_id: meta.thread_id,
    rfc_message_id: meta.rfc_message_id || null,
    received_at: meta.received_at,
    subject: meta.subject,

    enquirer_name: extracted.enquirer_name || null,
    email: extracted.email || null,
    phone: extracted.phone || null,

    property_address: extracted.property_address || null,
    property_ref: extracted.property_ref || null,
    property_price: extracted.property_price || null,

    enquiry_message: extracted.enquiry_message || null,
    applicant_wants: extracted.applicant_wants || null,
    viewing_requested: extracted.viewing_requested === true,
    enquiry_intent: extracted.enquiry_intent || null,

    moving_date: extracted.moving_date || null,
    tenancy_duration: extracted.tenancy_duration || null,
    moving_with: extracted.moving_with || null,
    occupants: extracted.occupants || null,
    pets: extracted.pets || null,
    smokers: extracted.smokers || null,
    first_time_renter: extracted.first_time_renter || null,
    employment: extracted.employment || null,
    affordability: extracted.affordability || null,
    guarantor: extracted.guarantor || null,
    adverse_credit: extracted.adverse_credit || null,
    parking_required: extracted.parking_required || null
  };

  // ---- Which qualification fields do we already have? ----
  const qualFields = [
    'employment', 'affordability', 'adverse_credit',
    'moving_date', 'pets', 'smokers', 'first_time_renter'
  ];
  const known = qualFields.filter((f) => rec[f]);
  const missing = qualFields.filter((f) => !rec[f]);

  rec.known_qualification = known;
  rec.missing_qualification = missing;

  // Rightmove typically arrives pre-qualified. Anything else does not.
  rec.is_pre_qualified = known.length >= 4;

  // Human-readable summary of what we already know — fed to the draft prompt
  // so the AI never re-asks a question the enquirer has already answered.
  rec.known_summary = known.length
    ? known.map((f) => `${f.replace(/_/g, ' ')}: ${rec[f]}`).join('; ')
    : 'No qualification details supplied with this enquiry.';

  // Flag records that need a human before anything is sent
  rec.needs_attention = !rec.email || !rec.property_ref;

  results.push({ json: rec });
}

return results;

// ─── CONFIGURE ────────────────────────────────────────────────────────────
const AGENCY_NAME = 'Your Letting Agency';           // used in the AI reply and email branding
const FORM_BASE   = 'https://YOUR_APPLICATION_FORM_URL';  // your pre-qualification / application form; ?ref=<property ref> is appended
const AUTO_SEND   = false;  // false: EVERY reply becomes a Gmail draft for staff approval (recommended start).
                            // true: safe, link-bearing replies to fresh enquiries send automatically; everything else still drafts.
const AUTO_SEND_FRESH_HOURS = 2;  // auto-send only within this window of the enquiry arriving — protects against
                                  // a first-run backlog or a re-import blasting out replies to days-old unread mail.
// ─── END CONFIGURE ────────────────────────────────────────────────────────

function altLink(ref, enquiryId) {
  return `${FORM_BASE}/?ref=${encodeURIComponent(ref)}`
    + (enquiryId ? `&e=${encodeURIComponent(enquiryId)}` : '');
}
function norm(s) { return String(s || '').toLowerCase().replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim(); }

// Rows from the Properties tab (Read Properties Sheet runs once and returns every row).
const rows = $input.all().map((r) => r.json).filter((r) => r && (r.ref || r.address));
// A property counts as available unless its status column says otherwise.
const isAvailable = (r) => {
  const s = norm(r.status || r.available || 'available');
  return !/let|unavailable|withdrawn|gone|no\b/.test(s);
};

const results = [];
const enquiries = $('Normalise Fields and Detect Gaps').all();

for (const e of enquiries) {
  const rec = { ...e.json };
  rec.agency_name = AGENCY_NAME;
  const enquiryId = rec.message_id || rec.thread_id || '';

  // ---- Match the enquiry to a property row: ref first, then address overlap ----
  let match = null;
  const refN = norm(rec.property_ref);
  if (refN) {
    match = rows.find((r) => {
      const rn = norm(r.ref);
      return rn && (rn === refN || refN.includes(rn) || rn.includes(refN));
    }) || null;
  }
  if (!match && rec.property_address) {
    const tokens = norm(rec.property_address).split(' ').filter((t) => t.length > 2);
    let best = null, bestScore = 0;
    for (const r of rows) {
      const rn = norm(r.address);
      let score = 0;
      for (const t of tokens) if (rn.includes(t)) score++;
      if (score > bestScore) { bestScore = score; best = r; }
    }
    if (best && bestScore >= 2) match = best;  // need at least two address words in common
  }

  // Default to available: only ever say "it's been let" when the sheet positively
  // says so, so a missing row never produces a wrong "sorry, it's gone".
  rec.property_available = true;
  rec.alternatives = [];

  if (match) {
    rec.property_ref = match.ref || rec.property_ref;
    rec.property_rent = match.rent || rec.property_price || null;
    rec.property_bedrooms = match.bedrooms ?? null;
    rec.property_available_from = match.available_from || null;
    rec.property_notes = match.notes || null;
    rec.property_available = isAvailable(match);
    if (!rec.property_available) {
      // Offer up to three similar AVAILABLE properties from the sheet instead.
      rec.alternatives = rows
        .filter((r) => r !== match && r.ref && isAvailable(r))
        .slice(0, 3)
        .map((a) => ({
          ref: a.ref, address: a.address, monthly_rent: a.rent,
          bedrooms: a.bedrooms, area: a.area || '', link: altLink(a.ref, enquiryId),
        }));
    }
  }

  if (rec.property_ref) rec.prequal_link = altLink(rec.property_ref, enquiryId);

  // If nothing resolved to one of our refs, flag for staff (no link possible).
  if (!rec.property_ref) {
    rec.prequal_link = null;
    rec.needs_attention = true;
    rec.attention_reason = 'Could not identify the property from the enquiry (no matching ref or address) - staff to check.';
  }

  // ---- Single source of truth for what the reply offers ---------------------
  // 'form'         : available + we have a link  -> CTA button
  // 'alternatives' : let + we found similar      -> "similar available" cards
  // 'none'         : anything else               -> NO link/button, invite a reply
  // Guarantees a "complete the form" message can never ship without a link.
  const hasLink = !!rec.prequal_link;
  const hasAlts = Array.isArray(rec.alternatives) && rec.alternatives.length > 0;
  if (rec.property_available && hasLink) rec.cta = 'form';
  else if (!rec.property_available && hasAlts) rec.cta = 'alternatives';
  else rec.cta = 'none';
  if (rec.cta !== 'form') rec.prequal_link = null;

  // ---- Auto-send and draft gates -------------------------------------------
  const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  const FRESH_MS = AUTO_SEND_FRESH_HOURS * 60 * 60 * 1000;
  let fresh = true;
  if (rec.received_at) {
    const t = Date.parse(rec.received_at);
    if (!Number.isNaN(t)) fresh = (Date.now() - t) < FRESH_MS;
  }
  rec.auto_send = AUTO_SEND
    && rec.cta === 'form'
    && EMAIL_RE.test(String(rec.email || '').trim())
    && fresh;

  // A reply is worth queuing when we have an email AND something to say — a form
  // link OR similar properties to offer. Alternatives do NOT need the original
  // property ref (the whole point is to offer OTHER properties), so an unmatched
  // enquiry still becomes a staff draft instead of being silently discarded.
  const hasEmail = !!(rec.email && String(rec.email).trim());
  rec.should_draft = hasEmail && (rec.cta === 'form' || rec.cta === 'alternatives');

  rec.outcome = rec.auto_send
    ? ('SENT (' + rec.cta + ')')
    : rec.should_draft
      ? ('draft (' + rec.cta + ')')
      : ('NO DRAFT: ' + (!hasEmail ? 'no email' : 'nothing to offer (no property match, no alternatives)'));

  results.push({ json: rec });
}
return results;

parameters.text:
=Write the reply email body only. No subject line, no signature — those are added automatically.

--- ENQUIRY ---
Agency: {{ $json.agency_name }}
Source: {{ $json.source }}
Name: {{ $json.enquirer_name }}
Property: {{ $json.property_address }} ({{ $json.property_rent }})
Their message: {{ $json.enquiry_message || 'None provided' }}
They asked for: {{ $json.applicant_wants || 'Not stated' }}
Viewing explicitly requested: {{ $json.viewing_requested }}

--- WHAT WE ALREADY KNOW ABOUT THEM ---
{{ $json.known_summary }}

--- STILL MISSING ---
{{ $json.missing_qualification.join(', ') || 'Nothing — all key details supplied' }}

--- PRE-QUALIFICATION FORM LINK ---
{{ $json.prequal_link }}

--- CALL TO ACTION ---
CTA: {{ $json.cta }}
Still available: {{ $json.property_available }}

--- SIMILAR AVAILABLE PROPERTIES (only relevant when CTA = alternatives; shown to them automatically) ---
{{ ($json.alternatives || []).map(a => a.address + ' - GBP ' + a.monthly_rent + ' pcm, ' + a.bedrooms + ' bed').join('; ') || 'None found right now' }}

parameters.jsCode:
// Build the final email: strip any LLM-inlined link or sign-off, then wrap the
// body in branded HTML. The CTA is driven by rec.cta (set in Match):
//   'form'         -> single branded "complete the form" button (link guaranteed)
//   'alternatives' -> "similar available" cards, each linking to its own form
//   'none'         -> no link/button (message invites a reply)
// ─── CONFIGURE ────────────────────────────────────────────────────────────
const BRAND_COLOR = '#2563EB';                 // your brand colour (buttons and links)
const SIGN_OFF    = 'The Lettings Team';       // or a named person, e.g. 'Jane Smith, Lettings Manager'
const PHONE       = '01234 567890';
const WEBSITE     = 'www.example.co.uk';
const OFFICE      = '1 High Street, Yourtown, AB1 2CD';
const LEGAL       = 'Add your company registration, redress scheme membership and client money protection details here.';
// ─── END CONFIGURE ────────────────────────────────────────────────────────

const results = [];
const enquiries = $('Match Property and Build Links').all();

for (let i = 0; i < enquiries.length; i++) {
  const rec = { ...enquiries[i].json };
  const AGENCY = rec.agency_name || 'Your Letting Agency';
  const ai = $input.all()[i].json;
  const cta = rec.cta || (rec.prequal_link ? 'form' : 'none');
  const alts = Array.isArray(rec.alternatives) ? rec.alternatives : [];
  const link = cta === 'form' ? (rec.prequal_link || '') : '';
  const showAlts = cta === 'alternatives' && alts.length > 0;
  let bodyText = (ai.text || ai.output || '').trim();

  // Strip any sign-off the AI added — the template below adds the ONLY sign-off.
  bodyText = bodyText.replace(/\n+\s*(kind regards|kindest regards|best regards|warm regards|warmest regards|regards|many thanks|best wishes|sincerely|yours sincerely|yours faithfully|the lettings team)\b[\s\S]*$/i, '').trim();

  // Strip any form link the AI inlined — the button below is the only link.
  bodyText = bodyText
    .replace(/[ \t]*(using )?(the )?(link|form)?( below| here)?[ \t]*:?[ \t]*\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/gi, '')
    .replace(/[ \t]*(using )?(the )?(link|form)?( below| here)?[ \t]*:?[ \t]*https?:\/\/\S+/gi, '')
    .replace(/[ \t]+/g, ' ').replace(/ +([.,])/g, '$1').replace(/ *\n/g, '\n').trim();

  const subject = showAlts
    ? (rec.property_address ? 'Re: ' + rec.property_address + ' - similar available properties' : 'Re: your property enquiry - similar available properties')
    : (rec.property_address ? 'Re: ' + rec.property_address + ' - your enquiry' : 'Re: your property enquiry');

  // ---- "similar available" block, only when we have alternatives to show ----
  let altsText = '';
  let altsHtml = '';
  if (showAlts) {
    altsText = '\n\nSimilar properties available now:\n'
      + alts.map((a) => '- ' + a.address + ' (GBP ' + a.monthly_rent + ' pcm, ' + a.bedrooms + ' bed): ' + a.link).join('\n');
    altsHtml = '<div style="margin:22px 0">'
      + alts.map((a) =>
          '<div style="border:1px solid #eceff3;border-radius:8px;padding:14px 16px;margin-bottom:12px">'
          + '<div style="font-weight:700;color:#1c1c28;font-size:15px">' + a.address + '</div>'
          + '<div style="color:#4b5563;font-size:13px;margin:4px 0 12px">GBP ' + a.monthly_rent + ' pcm&nbsp;&middot;&nbsp;' + a.bedrooms + ' bed' + (a.area ? '&nbsp;&middot;&nbsp;' + a.area : '') + '</div>'
          + '<a href="' + a.link + '" style="background:' + BRAND_COLOR + ';color:#ffffff;text-decoration:none;padding:10px 20px;border-radius:6px;font-weight:700;font-size:14px;display:inline-block">View &amp; apply</a>'
          + '</div>'
        ).join('')
      + '</div>';
  }

  rec.draft_subject = subject;
  rec.draft_body = bodyText
    + (link ? '\n\nComplete your pre-qualification form: ' + link : '')
    + altsText
    + '\n\nKind regards,\n\n' + SIGN_OFF + '\n' + AGENCY
    + '\nT: ' + PHONE + '\nWeb: ' + WEBSITE + '\nOffice: ' + OFFICE
    + '\n\n' + LEGAL;

  const bodyHtml = bodyText.replace(/\n/g, '<br>');
  const button = link
    ? '<div style="text-align:center;margin:26px 0"><a href="' + link + '" style="background:' + BRAND_COLOR + ';color:#ffffff;text-decoration:none;padding:14px 30px;border-radius:8px;font-weight:700;font-size:15px;display:inline-block">Complete the Pre-Qualification Form</a></div>'
    : '';

  rec.draft_body_html =
    '<div style="font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Arial,sans-serif;color:#1c1c28;line-height:1.5;max-width:600px;margin:0 auto">'
    + '<div style="padding:24px 22px;border:1px solid #eceff3;border-radius:8px;background:#ffffff">'
    + bodyHtml + button + altsHtml
    + '<div style="margin-top:24px;padding-top:18px;border-top:1px solid #eceff3;font-size:13px;color:#4b5563">'
    + 'Kind regards,<br><br><strong style="color:#1c1c28">' + SIGN_OFF + '</strong><br>' + AGENCY + '<br>'
    + 'T: ' + PHONE + '<br>Web: <a href="https://' + WEBSITE + '" style="color:' + BRAND_COLOR + '">' + WEBSITE + '</a><br>Office: ' + OFFICE + '</div>'
    + '<div style="margin-top:14px;font-size:11px;line-height:1.55;color:#9aa0ad">' + LEGAL + '</div>'
    + '</div></div>';

  results.push({ json: rec });
}
return results;

// TEST ENQUIRY — fake a parsed message so you can test without emailing.
// Match the property/ref to a row in your Properties tab to test the full path.
// Edit these to simulate different scenarios (source, pets, missing email, etc.).
return [{
  json: {
    id: 'test-' + Date.now(),        // unique each run
    threadId: '',
    rfc_message_id: '<test@example.com>',
    from: 'user@example.com',
    subject: 'Viewing request from the website (Property: 12 Example Street, Yourtown)',
    date: new Date().toUTCString(),
    snippet: '',
    html: '',
    headers: {},
    text: `Name: Test Applicant
Email: user@example.com
Phone: 07700 900123
Property: 12 Example Street, Yourtown
Property reference: AB1234
Message: Hi, I'd like to arrange a viewing — when are you available?`
  }
}];

// OPTIONAL: WhatsApp follow-up via the Meta WhatsApp Cloud API. Sends your
// approved template (with the form link as its button) to enquirers who left a
// deliverable phone number AND have a valid form link. Delete this node and the
// next one if you are not using WhatsApp.
// ─── CONFIGURE ────────────────────────────────────────────────────────────
const PHONE_ID     = 'YOUR_WHATSAPP_PHONE_NUMBER_ID';  // from Meta Business > WhatsApp > API Setup
const TEMPLATE     = 'YOUR_TEMPLATE_NAME';             // an APPROVED template with two body variables and a URL button
const LANG         = 'en';                             // must match the template's language code
const COUNTRY_CODE = '44';                             // default country code for local numbers (44 = UK)
const FORM_BASE    = 'https://YOUR_APPLICATION_FORM_URL';  // same value as in "Match Property and Build Links"
// ─── END CONFIGURE ────────────────────────────────────────────────────────

function toE164(raw) {
  let d = String(raw || '').replace(/[^0-9]/g, '');
  if (!d) return '';
  if (d.startsWith('00')) d = d.slice(2);                          // 0044... -> 44...
  if (d.startsWith(COUNTRY_CODE)) return d;                        // already international
  if (d.startsWith('0')) return COUNTRY_CODE + d.slice(1);         // 07... -> 447...
  return d;                                                        // assume already international
}

function linkSuffix(link, ref, enquiryId) {
  // The template's URL button base should be FORM_BASE + '/{{1}}', so {{1}} is
  // the query suffix '?ref=..&e=..'. Prefer slicing the already-resolved link.
  if (link && link.indexOf(FORM_BASE) === 0) {
    return link.slice(FORM_BASE.length).replace(/^\//, '');
  }
  const parts = [];
  if (ref) parts.push('ref=' + encodeURIComponent(ref));
  if (enquiryId) parts.push('e=' + encodeURIComponent(enquiryId));
  return parts.length ? '?' + parts.join('&') : '';
}

const results = [];
for (const item of $input.all()) {
  const rec = { ...item.json };
  const to = toE164(rec.phone);
  if (!to || to.length < 11) continue;               // need a deliverable phone
  if (!(rec.cta === 'form' && rec.prequal_link)) continue;  // only safe, link-bearing enquiries

  const enquiryId = rec.message_id || rec.thread_id || '';
  const suffix = linkSuffix(rec.prequal_link, rec.property_ref, enquiryId)
    || ('?ref=' + (rec.property_ref || ''));
  const propLabel = String(rec.property_address || 'the property');

  rec.whatsapp_to = to;
  rec.whatsapp_phone_id = PHONE_ID;
  rec.whatsapp_payload = {
    messaging_product: 'whatsapp',
    to: to,
    type: 'template',
    template: {
      name: TEMPLATE,
      language: { code: LANG },
      components: [
        { type: 'body', parameters: [
          { type: 'text', text: String(rec.enquirer_name || 'there') },
          { type: 'text', text: propLabel },
        ]},
        { type: 'button', sub_type: 'url', index: '0', parameters: [
          { type: 'text', text: suffix },
        ]},
      ],
    },
  };
  results.push({ json: rec });
}
return results;
